lib = '''"""Shared helpers for ARC task programs."""

def find_line(grid, color=2):
    """Return the row index of the full-width horizontal line of a color."""
    return next(r for r in range(len(grid)) if set(grid[r]) == {color})


def fall_step(grid, r, c):
    """One gravity step down, clamped to the bottom row."""
    return min(r + 1, len(grid) - 1), c


def diagonal_rays(grid, blocked, r, c, dr, dcs, out, color=4):
    """Mark diagonal rays from (r, c) in direction dr for each dc in dcs,
    stopping at edges or cells of the blocking color (marked in `out`)."""
    h, w = len(grid), len(grid[0])
    for dc in dcs:
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != blocked:
            out[rr][cc] = color
            rr += dr
            cc += dc


def apply_moves(grid, moves, color=4):
    """Erase all color cells, then stamp their moved positions."""
    out = [row[:] for row in grid]
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color:
                out[r][c] = 0
    for r, c in moves:
        out[r][c] = color
    return out
